-- ------------------------------------------------------------
-- Domain: Measurement (4 concepts)
-- ------------------------------------------------------------

SELECT
    person_id,
    measurement_concept_id,
    measurement_date,
    measurement_datetime,
    CASE
        -- Reference unit: mmol/L (8753)
        -- Conversions are concept-specific: switching per measurement_concept_id
        WHEN measurement_concept_id IN (
            990001, -- Analyte A in serum
            990002 -- Analyte A in plasma
        ) THEN
            CASE
                WHEN unit_concept_id = 8753 THEN value_as_number
                WHEN unit_concept_id = 8636 THEN value_as_number * 2.5 -- convert g/L (8636) -> mmol/L (8753)
                WHEN unit_concept_id = 8840 THEN value_as_number * 0.25 -- convert mg/dL (8840) -> mmol/L (8753)
                ELSE value_as_number -- unknown unit, no conversion: value kept as-is
            END
        WHEN measurement_concept_id = 990003 THEN -- Analyte A in urine
            CASE
                WHEN unit_concept_id = 8753 THEN value_as_number
                WHEN unit_concept_id = 8840 THEN value_as_number * 0.1 - 1.5 -- convert mg/dL (8840) -> mmol/L (8753)
                ELSE value_as_number -- unknown unit, no conversion: value kept as-is
            END
        ELSE value_as_number -- no conversion for this concept: value kept as-is
    END AS value_as_number,
    value_as_concept_id,
    CASE
        -- Conversions are concept-specific: relabel only the (concept, unit) pairs actually converted
        WHEN measurement_concept_id IN (990001, 990002) AND unit_concept_id IN (8753, 8636, 8840) THEN 8753
        WHEN measurement_concept_id = 990003 AND unit_concept_id IN (8753, 8840) THEN 8753
        ELSE unit_concept_id -- no conversion for this (concept, unit): kept as-is, value stays in its original unit
    END AS unit_concept_id,
    measurement_source_value,
    measurement_source_concept_id,
    unit_source_value
FROM measurement
WHERE measurement_concept_id IN (
    990001 -- Analyte A in serum
   ,990002 -- Analyte A in plasma
   ,990003 -- Analyte A in urine
   ,990004 -- Analyte A, no conversion
)
-- Optional: uncomment to drop rows whose unit cannot be converted to the reference unit
